import{_ as l,a0 as t,w as n,s as h,ao as c,I as d,x as i,a1 as a,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"Linux 系統中 sudo 命令的 10 個技巧 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 系統中 sudo 命令的 10 個技巧 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 系統中 sudo 命令的 10 個技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 系統中 sudo 命令的 10 個技巧 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180302 10 Quick Tips About sudo command for Linux systems","title":"Linux 系統中 sudo 命令的 10 個技巧","tag":"201804","desc":""},"relativePath":"201804/20180302 10 Quick Tips About sudo command for Linux systems.md","filePath":"[post].md"}'),p={name:"201804/20180302 10 Quick Tips About sudo command for Linux systems.md"};function r(u,s,g,k,b,m){const e=t("Link");return n(),h("div",null,[s[13]||(s[13]=c(`<h1 id="linux-系統中-sudo-命令的-10-個技巧" tabindex="-1">Linux 系統中 sudo 命令的 10 個技巧 <a class="header-anchor" href="#linux-系統中-sudo-命令的-10-個技巧" aria-label="Permalink to “Linux 系統中 sudo 命令的 10 個技巧”">​</a></h1><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/03/Linux-sudo-command-tips.jpg" alt="Linux-sudo-command-tips"></p><h3 id="概覽" tabindex="-1">概覽 <a class="header-anchor" href="#概覽" aria-label="Permalink to “概覽”">​</a></h3><p><code>sudo</code> 表示 “<strong>s</strong>uper<strong>u</strong>ser <strong>do</strong>”。 它允許已驗證的用户以其他用户的身份來運行命令。其他用户可以是普通用户或者超級用户。然而，大部分時候我們用它來以提升的權限來運行命令。</p><p><code>sudo</code> 命令與安全策略配合使用，默認安全策略是 <code>sudoers</code>，可以通過文件 <code>/etc/sudoers</code> 來配置。其安全策略具有高度可拓展性。人們可以開發和分發他們自己的安全策略作為插件。</p><h3 id="與-su-的區別" tabindex="-1">與 su 的區別 <a class="header-anchor" href="#與-su-的區別" aria-label="Permalink to “與 su 的區別”">​</a></h3><p>在 GNU/Linux 中，有兩種方式可以用提升的權限來運行命令：</p><ul><li>使用 <code>su</code> 命令</li><li>使用 <code>sudo</code> 命令</li></ul><p><code>su</code> 表示 “<strong>s</strong>witch <strong>u</strong>ser”。使用 <code>su</code>，我們可以切換到 root 用户並且執行命令。但是這種方式存在一些缺點：</p><ul><li>我們需要與他人共享 root 的密碼。</li><li>因為 root 用户為超級用户，我們不能授予受控的訪問權限。</li><li>我們無法審查用户在做什麼。</li></ul><p><code>sudo</code> 以獨特的方式解決了這些問題。</p><ol><li>首先，我們不需要妥協來分享 root 用户的密碼。普通用户使用他們自己的密碼就可以用提升的權限來執行命令。</li><li>我們可以控制 <code>sudo</code> 用户的訪問，這意味着我們可以限制用户只執行某些命令。</li><li>除此之外，<code>sudo</code> 用户的所有活動都會被記錄下來，因此我們可以隨時審查進行了哪些操作。在基於 Debian 的 GNU/Linux 中，所有活動都記錄在 <code>/var/log/auth.log</code> 文件中。</li></ol><p>本教程後面的部分闡述了這些要點。</p><h3 id="實際動手操作-sudo" tabindex="-1">實際動手操作 sudo <a class="header-anchor" href="#實際動手操作-sudo" aria-label="Permalink to “實際動手操作 sudo”">​</a></h3><p>現在，我們對 sudo 有了大致的瞭解。讓我們實際動手操作吧。為了演示，我使用 Ubuntu。但是，其它發行版本的操作應該是相同的。</p><h4 id="允許-sudo-權限" tabindex="-1">允許 sudo 權限 <a class="header-anchor" href="#允許-sudo-權限" aria-label="Permalink to “允許 sudo 權限”">​</a></h4><p>讓我們添加普通用户為 <code>sudo</code> 用户吧。在我的情形中，用户名為 <code>linuxtechi</code>。</p><ol><li>按如下所示編輯 <code>/etc/sudoers</code> 文件：</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo visudo</span></span></code></pre></div><ol start="2"><li>添加以下行來允許用户 <code>linuxtechi</code> 有 sudo 權限：</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi ALL=(ALL) ALL</span></span></code></pre></div><p>上述命令中：</p><ul><li><code>linuxtechi</code> 表示用户名</li><li>第一個 <code>ALL</code> 指示允許從任何終端、機器訪問 <code>sudo</code></li><li>第二個 <code>(ALL)</code> 指示 <code>sudo</code> 命令被允許以任何用户身份執行</li><li>第三個 <code>ALL</code> 表示所有命令都可以作為 root 執行</li></ul><h4 id="以提升的權限執行命令" tabindex="-1">以提升的權限執行命令 <a class="header-anchor" href="#以提升的權限執行命令" aria-label="Permalink to “以提升的權限執行命令”">​</a></h4><p>要用提升的權限執行命令，只需要在命令前加上 <code>sudo</code>，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cat /etc/passwd</span></span></code></pre></div><p>當你執行這個命令時，它會詢問 <code>linuxtechi</code> 的密碼，而不是 root 用户的密碼。</p><h4 id="以其他用户執行命令" tabindex="-1">以其他用户執行命令 <a class="header-anchor" href="#以其他用户執行命令" aria-label="Permalink to “以其他用户執行命令”">​</a></h4><p>除此之外，我們可以使用 <code>sudo</code> 以另一個用户身份執行命令。例如，在下面的命令中，用户 <code>linuxtechi</code> 以用户 <code>devesh</code> 的身份執行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo -u devesh whoami</span></span>
<span class="line"><span>[sudo] password for linuxtechi:</span></span>
<span class="line"><span>devesh</span></span></code></pre></div><h4 id="內置命令列為" tabindex="-1">內置命令列為 <a class="header-anchor" href="#內置命令列為" aria-label="Permalink to “內置命令列為”">​</a></h4><p><code>sudo</code> 的一個限制是 —— 它無法使用 Shell 的內置命令。例如， <code>history</code> 記錄是內置命令，如果你試圖用 <code>sudo</code> 執行這個命令，那麼會提示如下的未找到命令的錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo history</span></span>
<span class="line"><span>[sudo] password for linuxtechi:</span></span>
<span class="line"><span>sudo: history: command not found</span></span></code></pre></div><p><strong>訪問 root shell</strong></p><p>為了克服上述問題，我們可以訪問 root shell，並在那裏執行任何命令，包括 Shell 的內置命令。</p><p>要訪問 root shell, 執行下面的命令:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo bash</span></span></code></pre></div><p>執行完這個命令後——您將觀察到提示符變為井號（<code>#</code>）。</p><h3 id="技巧" tabindex="-1">技巧 <a class="header-anchor" href="#技巧" aria-label="Permalink to “技巧”">​</a></h3><p>這節我們將討論一些有用的技巧，這將有助於提高生產力。大多數命令可用於完成日常任務。</p><h4 id="以-sudo-用户執行之前的命令" tabindex="-1">以 sudo 用户執行之前的命令 <a class="header-anchor" href="#以-sudo-用户執行之前的命令" aria-label="Permalink to “以 sudo 用户執行之前的命令”">​</a></h4><p>讓我們假設你想用提升的權限執行之前的命令，那麼下面的技巧將會很有用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo !4</span></span></code></pre></div><p>上面的命令將使用提升的權限執行歷史記錄中的第 4 條命令。</p><h4 id="在-vim-裏面使用-sudo-命令" tabindex="-1">在 Vim 裏面使用 sudo 命令 <a class="header-anchor" href="#在-vim-裏面使用-sudo-命令" aria-label="Permalink to “在 Vim 裏面使用 sudo 命令”">​</a></h4><p>很多時候，我們編輯系統的配置文件時，在保存時才意識到我們需要 root 訪問權限來執行此操作。因為這個可能讓我們丟失我們對文件的改動。沒有必要驚慌，我們可以在 Vim 中使用下面的命令來解決這種情況：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:w !sudo tee %</span></span></code></pre></div><p>上述命令中：</p><ul><li>冒號 (<code>:</code>) 表明我們處於 Vim 的退出模式</li><li>感嘆號 (<code>!</code>) 表明我們正在運行 shell 命令</li><li><code>sudo</code> 和 <code>tee</code> 都是 shell 命令</li><li>百分號 (<code>%</code>) 表明從當前行開始的所有行</li></ul><h4 id="使用-sudo-執行多個命令" tabindex="-1">使用 sudo 執行多個命令 <a class="header-anchor" href="#使用-sudo-執行多個命令" aria-label="Permalink to “使用 sudo 執行多個命令”">​</a></h4><p>至今我們用 <code>sudo</code> 只執行了單個命令，但我們可以用它執行多個命令。只需要用分號 (<code>;</code>) 隔開命令，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo -- bash -c &#39;pwd; hostname; whoami&#39;</span></span></code></pre></div><p>上述命令中</p><ul><li>雙連字符 (<code>--</code>) 停止命令列切換</li><li><code>bash</code> 表示要用於執行命令的 shell 名稱</li><li><code>-c</code> 選項後面跟着要執行的命令</li></ul><h4 id="無密碼運行-sudo-命令" tabindex="-1">無密碼運行 sudo 命令 <a class="header-anchor" href="#無密碼運行-sudo-命令" aria-label="Permalink to “無密碼運行 sudo 命令”">​</a></h4><p>當第一次執行 <code>sudo</code> 命令時，它會提示輸入密碼，默認情形下密碼被緩存 15 分鐘。但是，我們可以避免這個操作，並使用 <code>NOPASSWD</code> 關鍵字禁用密碼認證，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi ALL=(ALL) NOPASSWD: ALL</span></span></code></pre></div><h4 id="限制用户執行某些命令" tabindex="-1">限制用户執行某些命令 <a class="header-anchor" href="#限制用户執行某些命令" aria-label="Permalink to “限制用户執行某些命令”">​</a></h4><p>為了提供受控訪問，我們可以限制 <code>sudo</code> 用户只執行某些命令。例如，下面的行只允許執行 <code>echo</code> 和 <code>ls</code> 命令 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi ALL=(ALL) NOPASSWD: /bin/echo /bin/ls</span></span></code></pre></div><h4 id="深入瞭解-sudo" tabindex="-1">深入瞭解 sudo <a class="header-anchor" href="#深入瞭解-sudo" aria-label="Permalink to “深入瞭解 sudo”">​</a></h4><p>讓我們進一步深入瞭解 <code>sudo</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /usr/bin/sudo</span></span>
<span class="line"><span>-rwsr-xr-x 1 root root 145040 Jun 13  2017 /usr/bin/sudo</span></span></code></pre></div><p>如果仔細觀察文件權限，則發現 <code>sudo</code> 上啓用了 setuid 位。當任何用户運行這個二進制文件時，它將以擁有該文件的用户權限運行。在所示情形下，它是 root 用户。</p><p>為了演示這一點，我們可以使用 <code>id</code> 命令，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ id</span></span>
<span class="line"><span>uid=1002(linuxtechi) gid=1002(linuxtechi) groups=1002(linuxtechi)</span></span></code></pre></div><p>當我們不使用 <code>sudo</code> 執行 <code>id</code> 命令時，將顯示用户 <code>linuxtechi</code> 的 id。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo id</span></span>
<span class="line"><span>uid=0(root) gid=0(root) groups=0(root)</span></span></code></pre></div><p>但是，如果我們使用 <code>sudo</code> 執行 <code>id</code> 命令時，則會顯示 root 用户的 id。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>從這篇文章可以看出 —— <code>sudo</code> 為普通用户提供了更多受控訪問。使用這些技術，多用户可以用安全的方式與 GNU/Linux 進行交互。</p><hr>`,72)),d("p",null,[s[1]||(s[1]=i("via: ",-1)),a(e,{href:"https://www.linuxtechi.com/quick-tips-sudo-command-linux-systems/"},{default:o(()=>[...s[0]||(s[0]=[i("https://www.linuxtechi.com/quick-tips-sudo-command-linux-systems/",-1)])]),_:1})]),d("p",null,[s[5]||(s[5]=i("作者：",-1)),a(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:o(()=>[...s[2]||(s[2]=[i("Pradeep Kumar",-1)])]),_:1}),s[6]||(s[6]=i(" 譯者：",-1)),a(e,{href:"https://github.com/szcf-weiya"},{default:o(()=>[...s[3]||(s[3]=[i("szcf-weiya",-1)])]),_:1}),s[7]||(s[7]=i(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:o(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),d("p",null,[s[10]||(s[10]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:o(()=>[...s[9]||(s[9]=[i("Linux中國",-1)])]),_:1}),s[12]||(s[12]=i(" 榮譽推出",-1))])])}const L=l(p,[["render",r]]);export{y as __pageData,L as default};
